INSERT INTO permissions (code, description) VALUES ('ATTENDANCE_CREATE','Create attendance'),('ATTENDANCE_READ','Read attendance'),('LEAVE_CREATE','Create leave requests'),('LEAVE_READ','Read leave requests'),('LEAVE_APPROVE','Approve leave requests'),('EOD_CREATE','Create and submit EOD reports'),('EOD_READ','Read EOD reports'),('EOD_REVIEW','Review EOD reports') ON CONFLICT (code) DO NOTHING;
INSERT INTO role_permissions (role_id, permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.name='SUPER_ADMIN' AND r.platform_role=TRUE AND p.code IN ('ATTENDANCE_CREATE','ATTENDANCE_READ','LEAVE_CREATE','LEAVE_READ','LEAVE_APPROVE','EOD_CREATE','EOD_READ','EOD_REVIEW') ON CONFLICT DO NOTHING;
